<?php require_once __DIR__.'/_layout.php'; admin_bat_buoc_dang_nhap(); $loi=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if(!admin_kiem_tra_csrf()) $loi='Yêu cầu không hợp lệ.'; else { $ten=trim($_POST['ten_the_loai']??''); $id=(int)($_POST['id']??0); if($ten==='')$loi='Tên thể loại không được để trống.'; else { $st=$ket_noi->prepare($id?'UPDATE dm_the_loai SET ten_the_loai=:ten WHERE id=:id':'INSERT INTO dm_the_loai (ten_the_loai) VALUES (:ten)'); $st->execute($id?['ten'=>$ten,'id'=>$id]:['ten'=>$ten]); header('Location: the-loai.php?ok=1');exit; } }} if(isset($_GET['xoa'])){ $id=(int)$_GET['xoa']; $st=$ket_noi->prepare('SELECT COUNT(*) FROM sach WHERE the_loai=:id');$st->execute(['id'=>$id]); if($st->fetchColumn()>0)$loi='Không thể xóa thể loại đang có sách.'; else {$ket_noi->prepare('DELETE FROM dm_the_loai WHERE id=:id')->execute(['id'=>$id]);header('Location: the-loai.php?ok=1');exit;}} $sua=null;if(isset($_GET['sua'])){$st=$ket_noi->prepare('SELECT * FROM dm_the_loai WHERE id=:id');$st->execute(['id'=>(int)$_GET['sua']]);$sua=$st->fetch();}$ds=$ket_noi->query('SELECT tl.*,COUNT(s.id) so_sach FROM dm_the_loai tl LEFT JOIN sach s ON s.the_loai=tl.id GROUP BY tl.id ORDER BY tl.ten_the_loai')->fetchAll(); admin_header('Thể loại'); ?><h1>Quản lý thể loại</h1><?php if($loi):?><p class="notice error"><?=htmlspecialchars($loi)?></p><?php endif;if(isset($_GET['ok'])):?><p class="notice ok">Đã lưu thay đổi.</p><?php endif;?><form class="card" method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=$sua['id']??''?>"><label>Tên thể loại</label><input required name="ten_the_loai" value="<?=htmlspecialchars($sua['ten_the_loai']??'')?>"><p class="actions"><button><?= $sua?'Lưu thay đổi':'Thêm thể loại'?></button><?php if($sua):?><a class="btn alt" href="the-loai.php">Hủy</a><?php endif;?></p></form><br><table><tr><th>Tên thể loại</th><th>Số sách</th><th></th></tr><?php foreach($ds as $tl):?><tr><td><?=htmlspecialchars($tl['ten_the_loai'])?></td><td><?=$tl['so_sach']?></td><td><a href="?sua=<?=$tl['id']?>">Sửa</a><?php if(!$tl['so_sach']):?> · <a href="?xoa=<?=$tl['id']?>" onclick="return confirm('Xóa thể loại này?')">Xóa</a><?php endif;?></td></tr><?php endforeach;?></table><?php admin_footer();
